INSERT IGNORE INTO `tour_transfer_prices` (`region`,`duty_code`,`location_type`,`point_a`,`point_b`,`route_description`,`service`,`distance_km`,`start_time`,`duration_min`,`day_schedule`,`valid_from`,`valid_to`,`vehicle`,`price`) VALUES
('gobustan + boulevard tour',NULL,'Hotel','Hotel','41',41,'PrivateTransfer',NULL,NULL,NULL,'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape   Rock paintings of Gobustan were first discovered in 1939    by archaeologist I. Jafarzade. On this territory there are    many traces of primitive inhabitance of people belong to   the period of the Paleolithic and Mesolithic. Rock    engravings of Gobustan cover a long historical period    nearly 15,000 years. In the Gobustan can be found rock   paintings created in the primitive epoch and up to the    \\Middle Ages, nowadays there are about 6,000 drawings.    The territory of Gobustan had favorable living conditions    in the Mesolithic, Neolithic and Bronze Age and was   inhabited by hunters and fishermen. Petroglyphs of the   Gobustan museum included to the UNESCO World Heritage List. + Walking tour starts along the Baku Boulevard followed by: -Mini Venice of Baku   -Carpet Museum -Deniz Mall    -Ferries Wheel ride    -Carpet Museums   -Boat cruise    -Cristal Hall   -Biking Area',NULL,NULL,'Guides (O)',47.0),
('gobustan + panaromic city tour',NULL,'Hotel','Hotel','41',41,'PrivateTransfer',NULL,NULL,NULL,'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape   Rock paintings of Gobustan were first discovered in 1939    by archaeologist I. Jafarzade. On this territory there are    many traces of primitive inhabitance of people belong to   the period of the Paleolithic and Mesolithic. Rock    engravings of Gobustan cover a long historical period    nearly 15,000 years. In the Gobustan can be found rock   paintings created in the primitive epoch and up to the    \\Middle Ages, nowadays there are about 6,000 drawings.    The territory of Gobustan had favorable living conditions    in the Mesolithic, Neolithic and Bronze Age and was   inhabited by hunters and fishermen. Petroglyphs of the   Gobustan museum included to the UNESCO World Heritage List. + Panoramic City Tour starts with panoramic full evening city view of Baku followed by:      -Highland Park (Which is the highest point in the Azerbaijani capital,    opening a panoramic view of the city and its bay. The city''s residents   and visitors often come here to see a bird''s eye view of Baku, and    just have a walk. The Upland Park can be reached by cable railway    (funicular) in 7-8 minutes from the boulevard or by climbing up the   endless stone stairs.)      -Flame Towers (The city''s tallest building. The height of 182 m.    Flame Towers - consisting of three high-rise buildings in the complex.)',NULL,NULL,'Sedan - 4 Seaters (Local Speaking)',41.0),
